tog=lambda on=True:'<span class="tog%s"></span>'%('' if on else ' off')
sel=lambda t,w='1 1 160px': inp(t+' <span class="mute" style="margin-left:auto">▾</span>',w)
def inject(name,html,marker,newh=None):
    p=ROOT+name+'.dc.html'; s=open(p).read()
    if marker in s: return
    s=s.replace('</main>','<!--'+marker+'-->'+html+'</main>',1)
    if newh: s=re.sub(r'"height":\d+\}',f'"height":{newh}}}',s,count=1)
    open(p,'w').write(s)
